// === Tab: mySketch ===
// --- FLUID SETTINGS ---
const N = 128; // Higher resolution for smaller "cells"
const iter = 4; 
let density, vx, vy, vx0, vy0;

let radius_, angle = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  radius_ = max(width, height) * 0.25;

  let numCells = (N + 2) * (N + 2);
  density = new Float32Array(numCells);
  vx = new Float32Array(numCells);
  vy = new Float32Array(numCells);
  vx0 = new Float32Array(numCells);
  vy0 = new Float32Array(numCells);

  colorMode(HSB, 255);
}

function draw() {
  background(0);

  // 1. INPUTS
  let mX = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width) * N;
  let mY = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height) * N;
  let isAltPressed = keyIsDown(18);

  // Mouse Interaction
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) || ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0)) {
    // Add density (color)
    addDensity(floor(mX), floor(mY), 300);

    // Add velocity based on mouse movement
    let vMouseX = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * 0.5;
    let vMouseY = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * 0.5;
    addVelocity(floor(mX), floor(mY), vMouseX, vMouseY);

    // ALT PULL LOGIC: If Alt is held, suck fluid toward mouse
    if (isAltPressed) {
      for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
           let dx = mX - i;
           let dy = mY - j;
           let d2 = dx*dx + dy*dy;
           if(d2 < 400) { // Pull radius
             addVelocity(i, j, dx * 0.05, dy * 0.05);
           }
        }
      }
    }
  }

  // 2. SOLVE & RENDER
  step();
  renderFluidSmooth(); // Optimized rendering

  angle += 0.02;
}

function renderFluidSmooth() {
  let cellW = width / N;
  let cellH = height / N;

  // We use a small rectangle "oversize" or a filter to hide grid lines
  noStroke();
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      let d = density[i + j * N];
      if (d > 0.1) {
        // Map density to a watery blue-cyan range
        let h = map(d, 0, 255, 140, 190); 
        fill(h, 200, 255, constrain(d, 0, 255));
        // Drawing slightly larger than cell width removes the "gaps"
        rect(i * cellW, j * cellH, cellW + 0.5, cellH + 0.5);
      }
    }
  }
}

// --- CORE SOLVER FUNCTIONS ---
function addDensity(x, y, amount) {
  if (x >= 0 && x < N && y >= 0 && y < N) density[x + y * N] += amount;
}

function addVelocity(x, y, px, py) {
  if (x >= 0 && x < N && y >= 0 && y < N) {
    vx[x + y * N] += px;
    vy[x + y * N] += py;
  }
}

function step() {
  let visc = 0.000001;
  let diff = 0.000001;
  let dt = 0.1;

  diffuse(1, vx0, vx, visc, dt);
  diffuse(2, vy0, vy, visc, dt);
  project(vx0, vy0, vx, vy);
  advect(1, vx, vx0, vx0, vy0, dt);
  advect(2, vy, vy0, vx0, vy0, dt);
  project(vx, vy, vx0, vy0);
  diffuse(0, vx0, density, diff, dt);
  advect(0, density, vx0, vx, vy, dt);

  // Fade out density over time for a "smoke/water" effect
  for (let i = 0; i < density.length; i++) density[i] *= 0.99;
}

// --- NAVIER-STOKES MATH ---
function diffuse(b, x, x0, diff, dt) {
  let a = dt * diff * (N - 2) * (N - 2);
  lin_solve(b, x, x0, a, 1 + 4 * a);
}

function lin_solve(b, x, x0, a, c) {
  for (let k = 0; k < iter; k++) {
    for (let j = 1; j < N - 1; j++) {
      for (let i = 1; i < N - 1; i++) {
        x[i + j * N] = (x0[i + j * N] + a * (x[i + 1 + j * N] + x[i - 1 + j * N] + x[i + (j + 1) * N] + x[i + (j - 1) * N])) / c;
      }
    }
  }
}

function project(vX, vY, p, div) {
  for (let j = 1; j < N - 1; j++) {
    for (let i = 1; i < N - 1; i++) {
      div[i + j * N] = -0.5 * (vX[i + 1 + j * N] - vX[i - 1 + j * N] + vY[i + (j + 1) * N] - vY[i + (j - 1) * N]) / N;
      p[i + j * N] = 0;
    }
  }
  lin_solve(0, p, div, 1, 4);
  for (let j = 1; j < N - 1; j++) {
    for (let i = 1; i < N - 1; i++) {
      vX[i + j * N] -= 0.5 * (p[i + 1 + j * N] - p[i - 1 + j * N]) * N;
      vY[i + j * N] -= 0.5 * (p[i + (j + 1) * N] - p[i + (j - 1) * N]) * N;
    }
  }
}

function advect(b, d, d0, vX, vY, dt) {
  let i0, i1, j0, j1, x, y, s0, s1, t0, t1;
  let dtx = dt * (N - 2);
  let dty = dt * (N - 2);

  for (let j = 1; j < N - 1; j++) {
    for (let i = 1; i < N - 1; i++) {
      x = i - dtx * vX[i + j * N];
      y = j - dty * vY[i + j * N];
      if (x < 0.5) x = 0.5; if (x > N - 1.5) x = N - 1.5;
      i0 = floor(x); i1 = i0 + 1;
      if (y < 0.5) y = 0.5; if (y > N - 1.5) y = N - 1.5;
      j0 = floor(y); j1 = j0 + 1;
      s1 = x - i0; s0 = 1 - s1;
      t1 = y - j0; t0 = 1 - t1;
      d[i + j * N] = s0 * (t0 * d0[i0 + j0 * N] + t1 * d0[i0 + j1 * N]) +
                     s1 * (t0 * d0[i1 + j0 * N] + t1 * d0[i1 + j1 * N]);
    }
  }
}

function keyPressed() {
  if (keyCode === 18) return false;
}

